{
  "name": "CLARIOstar多功能酶标仪",
  "name_en": "CLARIOstar multimode microplate reader",
  "manufacturer": "BMG LABTECH",
  "description": "CLARIOstar 是一款多功能微孔板读板仪，可对微孔板样品进行吸光度、荧光和发光检测，常用于生化分析、细胞实验、药物筛选和其他高通量实验。",
  "description_en": "The CLARIOstar is a multimode microplate reader used to measure absorbance, fluorescence, and luminescence in microplate samples. It is commonly used for biochemical assays, cell-based experiments, drug screening, and other high-throughput laboratory workflows.",
  "tag_hints": [
    "microplate reader",
    "multimode detection",
    "absorbance measurement",
    "fluorescence measurement",
    "luminescence assay",
    "high-throughput screening",
    "96-well plates"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭微孔板托盘。",
      "description_en": "Close the microplate tray."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化酶标仪并使其进入可操作状态。",
      "description_en": "Initialize the plate reader and prepare it for operation."
    },
    {
      "action_name": "auto-open",
      "description": "打开微孔板托盘。",
      "description_en": "Open the microplate tray."
    },
    {
      "action_name": "auto-read_absorbance",
      "description": "测量微孔板在指定波长下的吸光度或透过率。",
      "description_en": "Measure absorbance or transmittance of the microplate at a specified wavelength."
    },
    {
      "action_name": "auto-read_command_status",
      "description": "读取当前命令的执行状态。",
      "description_en": "Read the execution status of the current command."
    },
    {
      "action_name": "auto-read_fluorescence",
      "description": "测量微孔板样品的荧光信号。",
      "description_en": "Measure fluorescence signals from microplate samples."
    },
    {
      "action_name": "auto-read_luminescence",
      "description": "测量微孔板样品的发光信号。",
      "description_en": "Measure luminescence signals from microplate samples."
    },
    {
      "action_name": "auto-read_resp",
      "description": "读取设备返回的响应数据。",
      "description_en": "Read response data returned by the device."
    },
    {
      "action_name": "auto-request_eeprom_data",
      "description": "读取设备 EEPROM 中存储的信息。",
      "description_en": "Request information stored in the device EEPROM."
    },
    {
      "action_name": "auto-send",
      "description": "向酶标仪发送控制命令。",
      "description_en": "Send a control command to the plate reader."
    },
    {
      "action_name": "auto-setup",
      "description": "设置并准备酶标仪进行通信和操作。",
      "description_en": "Set up the plate reader for communication and operation."
    },
    {
      "action_name": "auto-stop",
      "description": "停止当前读板或设备操作。",
      "description_en": "Stop the current read or device operation."
    },
    {
      "action_name": "auto-get_stat",
      "description": "获取设备状态。",
      "description_en": "Get device status."
    }
  ]
}

